      arm: new T.BoxGeometry(0.11, 0.58, 0.12).translate(0, -0.27, 0), head: new T.IcosahedronGeometry(0.15, 0),
      tricorne: new T.ConeGeometry(0.26, 0.14, 3), roundHat: new T.CylinderGeometry(0.26, 0.26, 0.04, 8),
