        if (a === 'even') { [2.6, 5.0, 7.4].forEach(function (t0, j) { volley(t0, j % 2 ? backRegs : frontRegs, -1); }); [3.8, 6.2, 8.6].forEach(function (t0) { volley(t0, militia, 1); }); }
        if (a === 'driveback') { volley(2.6, militia, 1); }
